import { diyGetInfo, diySave } from '@/api/diy';
import { mapMutations } from 'vuex';
import rightConfig from '@/components/rightConfig/index';
import links from './links';
export default {
  name: "index",
  components: {
    rightConfig: rightConfig,
    links: links
  },
  data: function data() {
    return {
      configName: '',
      iframeUrl: '',
      setConfig: '',
      updataConfig: '',
      pageId: 0
    };
  },
  created: function created() {
    var _this = this;
    var pageId = this.$route.query.id;
    var names = this.$route.query.name;
    this.setConfig = 'admin/' + names + '/setConfig';
    this.updataConfig = 'admin/' + names + '/updataConfig';
    this.pageId = parseInt(pageId);
    this.iframeUrl = "".concat(location.origin, "?type=iframeMakkMinkkJuan");
    diyGetInfo(parseInt(pageId)).then(function (datas) {
      var data = datas.data.info.value;
      _this.upData(data);
    });
  },
  mounted: function mounted() {
    //监听子页面给当前页面传值
    window.addEventListener("message", this.handleMessage, false);
  },
  methods: {
    //接收iframe值
    handleMessage: function handleMessage(event) {
      if (event.data.name) {
        this.configName = event.data.name;
        this.add(event.data.name);
      }
    },
    add: function add(data) {
      this.$store.commit(this.setConfig, data);
    },
    upData: function upData(data) {
      this.$store.commit(this.updataConfig, data);
    } // ...mapMutations({
    //     add: 'diy/setConfig',
    //     upData:'diy/updataConfig'
    // })
  }
};
